from examples_html_utils import executable_examples, validate_examples_payload


def test_path_steps_do_not_drop_python_examples() -> None:
    payload = {
        "examples": [
            {
                "title": "Установка Python в PATH",
                "description": "Галочка установщика.",
                "code": "1. Откройте установщик\n2. Add Python to PATH",
            },
            {
                "title": "Проверка версии",
                "description": "Показывает версию интерпретатора.",
                "code": "import sys\nprint(sys.version)",
            },
            {
                "title": "Где лежит Python",
                "description": "Показывает путь к интерпретатору.",
                "code": "import sys\nprint(sys.executable)",
            },
        ]
    }
    kept = executable_examples(payload)
    assert [item["title"] for item in kept] == [
        "Проверка версии",
        "Где лежит Python",
    ]
    validate_examples_payload(payload, min_examples=1)


def test_only_shell_is_rejected() -> None:
    payload = {
        "examples": [
            {
                "title": "Установка Python в PATH",
                "description": "Команды оболочки.",
                "code": "export PATH=$PATH:/usr/bin\necho $PATH",
            }
        ]
    }
    assert executable_examples(payload) == []
    try:
        validate_examples_payload(payload, min_examples=1)
    except ValueError as exc:
        assert "терминала" in str(exc)
    else:
        raise AssertionError("ожидался ValueError")


